const MELEE_RANGE = 1.5;

type EnemyState = "patrol" | "chase" | "dead";

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly navAgent: NavigationAgent3D;
  health = 60;
  alive = true;
  #state: EnemyState = "patrol";
  #rifle: Mesh;
  #weapon = new Hitscan(FIRE_RANGE, 0.5);
  #fireTimer = 0;
  #patrolTarget: Vector3;
  #lastPlayerSeen: Vector3 | undefined;
  #canSeePlayerThisFrame = false;
  #updateHandle: ScheduleHandle | undefined;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: {
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.36),
    });

    this.navAgent = new NavigationAgent3D({
      radius: 0.4,
      height: 1.6,
      maxSpeed: MOVE_SPEED,
      physics: ctx.physics,
      object: this.mesh,
    });

    this.#rifle = createRifleVisual(materials);
    try {
      attachToBone(this.mesh, "RightHand", this.#rifle);
    } catch {
      this.mesh.add(this.#rifle);
      this.#rifle.position.set(0.3, -0.1, -0.2);
    }

    this.#patrolTarget = position.clone().add(
      new Vector3(
        (Math.random() - 0.5) * PATROL_RADIUS * 2,
        0,
        (Math.random() - 0.5) * PATROL_RADIUS * 2,
      ),
    );

    this.#updateHandle = ctx.every(0.2, () => this.#updateAI(ctx));
  }

  #updateAI(ctx: GameCtx): void {
    if (!this.alive) return;

    const player = ctx.entities.get("player");
    if (player === undefined || !(player instanceof (await import("./Player.js")).Player)) return;

