import { applyDirectDamage, applyRadiusDamage } from "../combat/damage.js";
import { Enemy } from "../entities/Enemy.js";
import { Pickup } from "../entities/Pickup.js";
import {
  FRIENDLY_LAYER,
  HOSTILE_LAYER,
  PLAYER_LAYER,
  Player,
  SPAWN,
  WORLD_LAYER,
