1	import type { ICtx, ScheduleHandle } from "@threenative/core";
2	import { attachToBone } from "@threenative/core";
3	import { CharacterBody3D, CollisionShape3D, NavigationAgent3D, type IPhysicsContext } from "@threenative/physics";
4	import { type Group, Mesh, Vector3 } from "three";
5	import { Hitscan } from "../weapons/Hitscan.js";
6	import { directSpaceState } from "../physics.js";
7	import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
8	import type { GameState } from "../state.js";
9	import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER, Player } from "./Player.js";
10	
11	type GameCtx = ICtx<GameState, IPhysicsContext>;
12	
13	const MOVE_SPEED = 3;
14	const PATROL_RADIUS = 8;
15	const DETECTION_RANGE = 12;
16	const FIRE_RANGE = 20;
17	const MELEE_RANGE = 1.5;
18	
19	type EnemyState = "patrol" | "chase" | "dead";
20	
21	export class Enemy {
22	  readonly mesh: Group;
23	  readonly body: CharacterBody3D;
24	  readonly navAgent: NavigationAgent3D;
25	  health = 60;
26	  alive = true;
27	  #state: EnemyState = "patrol";
28	  #rifle: Mesh;
29	  #weapon = new Hitscan(FIRE_RANGE, 0.5);
30	  #fireTimer = 0;
31	  #patrolTarget: Vector3;
32	  #lastPlayerSeen: Vector3 | undefined;
33	  #canSeePlayerThisFrame = false;
34	  #updateHandle: ScheduleHandle | undefined;
35	  #onFire: (origin: Vector3) => void;
36	
37	  constructor(
38	    ctx: GameCtx,
39	    materials: Parameters<typeof createEnemyVisual>[0],
40	    position: Vector3,
41	    options: {
42	      readonly onFire?: (origin: Vector3) => void;
43	    } = {},
44	  ) {
45	    this.#onFire = options.onFire ?? (() => undefined);
46	    this.mesh = createEnemyVisual(materials);
47	    this.mesh.position.copy(position);
48	    ctx.add(this.mesh);
49	
50	    this.body = new CharacterBody3D({
51	      collisionLayer: HOSTILE_LAYER,
52	      collisionMask: WORLD_LAYER | PLAYER_LAYER,
53	      autostep: { maxHeight: 0.25, minWidth: 0.18 },
54	      object: this.mesh,
55	      physics: ctx.physics,
56	      shape: CollisionShape3D.capsule(0.4, 0.36),
57	    });
58	
59	    this.navAgent = new NavigationAgent3D({
60	      radius: 0.4,
61	      height: 1.6,
62	      maxSpeed: MOVE_SPEED,
63	      physics: ctx.physics,
64	      object: this.mesh,
65	    });
66	
67	    this.#rifle = createRifleVisual(materials);
68	    try {
69	      attachToBone(this.mesh, "RightHand", this.#rifle);
70	    } catch {
71	      this.mesh.add(this.#rifle);
72	      this.#rifle.position.set(0.3, -0.1, -0.2);
73	    }
74	
75	    this.#patrolTarget = position.clone().add(
76	      new Vector3(
77	        (Math.random() - 0.5) * PATROL_RADIUS * 2,
78	        0,
79	        (Math.random() - 0.5) * PATROL_RADIUS * 2,
80	      ),
81	    );
82	
83	    this.#updateHandle = ctx.every(0.2, () => this.#updateAI(ctx));
84	  }
85	
86	  #updateAI(ctx: GameCtx): void {
87	    if (!this.alive) return;
88	
89	    const player = ctx.entities.get("player");
90	    if (player === undefined || !(player instanceof Player)) return;
91	
92	    const playerPos = player.mesh.position;
93	    const distance = this.mesh.position.distanceTo(playerPos);
94	    this.#canSeePlayerThisFrame = false;
95	
96	    if (distance < DETECTION_RANGE) {
97	      const hit = directSpaceState(ctx.physics).intersectRay({
98	        from: this.mesh.position.clone().add(new Vector3(0, 0.8, 0)),
99	        to: playerPos.clone().add(new Vector3(0, 0.8, 0)),
100	        collisionMask: WORLD_LAYER,
101	      });
102	      if (hit === undefined) {
103	        this.#canSeePlayerThisFrame = true;
104	        this.#lastPlayerSeen = playerPos.clone();
105	        this.#state = "chase";
106	      }
107	    }
108	
109	    if (this.#state === "chase") {
110	      if (!this.#canSeePlayerThisFrame && this.#lastPlayerSeen !== undefined) {
111	        const lostTime = 3;
112	        this.#updateHandle?.cancel();
113	        this.#updateHandle = ctx.after(lostTime, () => {
114	          this.#state = "patrol";
115	          this.#lastPlayerSeen = undefined;
116	        });
117	      }
118	    }
119	
120	    if (this.#state === "patrol" && this.mesh.position.distanceTo(this.#patrolTarget) < 0.5) {
121	      this.#patrolTarget = this.mesh.position.clone().add(
122	        new Vector3(
123	          (Math.random() - 0.5) * PATROL_RADIUS * 2,
124	          0,
125	          (Math.random() - 0.5) * PATROL_RADIUS * 2,
126	        ),
127	      );
128	    }
129	  }
130	
131	  update(ctx: GameCtx, dt: number): void {
132	    if (!this.alive) return;
133	
134	    this.#weapon.update(dt);
135	    this.#fireTimer -= dt;
136	
137	    const player = ctx.entities.get("player");
138	    if (player === undefined || !(player instanceof Player)) return;
