import type { ICtx, ScheduleHandle } from "@threenative/core";
import { attachToBone } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Mesh, Vector3 } from "three";
import { Hitscan } from "../weapons/Hitscan.js";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER, Player } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const MOVE_SPEED = 2.8;
const PATROL_RADIUS = 8;
const DETECTION_RANGE = 12;
const FIRE_RANGE = 20;
const LOST_TIME = 3;

type EnemyState = "patrol" | "chase" | "dead";

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  health = 60;
  alive = true;
  #state: EnemyState = "patrol";
  #rifle: Mesh;
  #weapon = new Hitscan(FIRE_RANGE, 0.5);
  #fireTimer = 0;
  #patrolTarget: Vector3;
  #lastPlayerSeen: Vector3 | undefined;
  #lostTimer = 0;
  #updateHandle: ScheduleHandle | undefined;
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: {
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.36),
    });

    this.#rifle = createRifleVisual(materials);
    try {
      attachToBone(this.mesh, "RightHand", this.#rifle);
    } catch {
      this.mesh.add(this.#rifle);
      this.#rifle.position.set(0.3, -0.1, -0.2);
    }

    this.#patrolTarget = position.clone().add(
      new Vector3(
        (Math.random() - 0.5) * PATROL_RADIUS * 2,
        0,
        (Math.random() - 0.5) * PATROL_RADIUS * 2,
      ),
    );

    this.#updateHandle = ctx.every(0.2, () => this.#updateAI(ctx));
  }

  #updateAI(ctx: GameCtx): void {
    if (!this.alive) return;

    const player = ctx.entities.get("player");
    if (player === undefined || !(player instanceof Player)) return;

    const playerPos = player.mesh.position;
    const distance = this.mesh.position.distanceTo(playerPos);

    if (distance < DETECTION_RANGE) {
      const rayOrigin = this.mesh.position.clone().add(new Vector3(0, 0.8, 0));
      const rayTarget = playerPos.clone().add(new Vector3(0, 0.8, 0));
      const hit = directSpaceState(ctx.physics).intersectRay({
        from: rayOrigin,
        to: rayTarget,
        collisionMask: WORLD_LAYER,
      });
      if (hit === undefined) {
        this.#lastPlayerSeen = playerPos.clone();
        this.#state = "chase";
        this.#lostTimer = 0;
        return;
      }
    }

    if (this.#state === "chase") {
      if (this.#lastPlayerSeen === undefined) return;
      this.#lostTimer += 0.2;
      if (this.#lostTimer >= LOST_TIME) {
        this.#state = "patrol";
        this.#lastPlayerSeen = undefined;
        this.#lostTimer = 0;
      }
    }

    if (this.#state === "patrol" && this.mesh.position.distanceTo(this.#patrolTarget) < 0.6) {
      this.#patrolTarget = this.mesh.position.clone().add(
        new Vector3(
          (Math.random() - 0.5) * PATROL_RADIUS * 2,
          0,
          (Math.random() - 0.5) * PATROL_RADIUS * 2,
        ),
      );
    }
  }

  update(ctx: GameCtx, dt: number): void {
    if (!this.alive) return;

    this.#weapon.update(dt);
    this.#fireTimer -= dt;

    const player = ctx.entities.get("player");
    if (player === undefined || !(player instanceof Player)) return;

    const playerPos = player.mesh.position;
    const distance = this.mesh.position.distanceTo(playerPos);
    let moveDirection = new Vector3(0, 0, 0);

    if (this.#state === "chase" && this.#lastPlayerSeen !== undefined) {
      const targetPos = this.#lastPlayerSeen;
      moveDirection = targetPos.clone().sub(this.mesh.position);
      if (moveDirection.length() > 0.1) {
        moveDirection.normalize().multiplyScalar(MOVE_SPEED);
      }

      if (distance < FIRE_RANGE && this.#fireTimer <= 0) {
        const direction = playerPos.clone().sub(this.mesh.position).normalize();
        const fireOrigin = this.mesh.position.clone().add(new Vector3(0.3, 0.9, 0));
        const hit = this.#weapon.fire(
          ctx.physics,
          fireOrigin,
          direction,
          WORLD_LAYER | PLAYER_LAYER,
        );
        if (hit?.body.id === player.body.body.id) {
          player.takeDamage(15);
        }
        this.#fireTimer = this.#weapon.cooldown;
        this.#onFire(fireOrigin);
      }
    } else if (this.#state === "patrol") {
      moveDirection = this.#patrolTarget.clone().sub(this.mesh.position);
      if (moveDirection.length() > 0.1) {
        moveDirection.normalize().multiplyScalar(MOVE_SPEED);
      }
    }

    this.body.velocity.x = moveDirection.x;
    this.body.velocity.z = moveDirection.z;
    this.body.moveAndSlide(dt);
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      health: this.health,
      position: this.mesh.position.toArray(),
      state: this.#state,
    };
  }

  dispose(): void {
    this.#updateHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

