export function createProjectileVisual(materials: ShooterMaterials): Mesh {
  return shadowed(new Mesh(new SphereGeometry(0.12, 4, 3), materials.trim), false);
}

export function createEnemyVisual(materials: ShooterMaterials): Group {
  const group = new Group();
  group.name = "enemy-visual";
  const body = block(0.8, 1.6, 0.8, materials.hostile);
  body.position.y = 0.8;
  group.add(body);
  const head = new Mesh(new SphereGeometry(0.35, 6, 4), materials.hostile);
  head.position.y = 1.8;
  head.castShadow = true;
  group.add(head);
  return group;
}

export function createRifleVisual(materials: ShooterMaterials): Mesh {
  const rifle = new Mesh(roundedBox(0.12, 0.12, 1.2), materials.trim);
  rifle.castShadow = true;
